            {
                customValidator!.DisplayErrors(errors);
                return;
            }

            isConfirmed = true;
        }
        finally
        {
            isSubmitting = false;
        }
    }

    private bool ValidateStep1()
    {
        var results = new List<System.ComponentModel.DataAnnotations.ValidationResult>();
        var ctx = new System.ComponentModel.DataAnnotations.ValidationContext(model);
        bool allValid = true;

        // Clear any prior custom errors before re-validating
        customValidator?.ClearErrors();
        var errors = new Dictionary<string, List<string>>();

        foreach (var fieldName in Step1Fields)
        {
            var prop = typeof(AppointmentFormModel).GetProperty(fieldName)!;
            var value = prop.GetValue(model);
            var fieldResults = new List<System.ComponentModel.DataAnnotations.ValidationResult>();
            var fieldCtx = new System.ComponentModel.DataAnnotations.ValidationContext(model)
            {
                MemberName = fieldName
            };

            if (!Validator.TryValidateProperty(value, fieldCtx, fieldResults))
            {
                allValid = false;
                errors[fieldName] = fieldResults.Select(r => r.ErrorMessage!).ToList();
            }
        }

        if (!allValid)
        {
            customValidator!.DisplayErrors(errors);
        }

        return allValid;
    }

    private async Task OnDoctorChanged()
    {
