@inject AppointmentService AppointmentSvc

<PageTitle>Book Appointment</PageTitle>

<h2>Book a Medical Appointment</h2>

@if (isConfirmed)
{
    <div class="alert alert-success mt-3">
        <h4>Appointment Confirmed!</h4>
        <p>
            <strong>@patientInfo.Name</strong>, your appointment with
            <strong>@appointmentDetails.Doctor</strong> on
            <strong>@appointmentDetails.Date?.ToString("MMMM d, yyyy")</strong> at
            <strong>@appointmentDetails.TimeSlot</strong> has been booked.
        </p>
    </div>
}
else
{
    <h4 class="mt-4">Step 1: Patient Information</h4>
    <EditForm EditContext="patientEditContext" OnValidSubmit="HandleStep1Submit" class="mb-4">
        <DataAnnotationsValidator />

        <div class="mb-3">
            <label class="form-label" for="patientName">Patient Name</label>
            <InputText id="patientName" class="form-control" @bind-Value="patientInfo.Name" />
            <ValidationMessage For="() => patientInfo.Name" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="email">Email</label>
            <InputText id="email" class="form-control" @bind-Value="patientInfo.Email" />
            <ValidationMessage For="() => patientInfo.Email" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="phone">Phone</label>
            <InputText id="phone" class="form-control" @bind-Value="patientInfo.Phone" />
            <ValidationMessage For="() => patientInfo.Phone" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="insurance">Insurance Provider</label>
            <InputSelect id="insurance" class="form-control" @bind-Value="patientInfo.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => patientInfo.InsuranceProvider" />
        </div>

        <button type="submit" class="btn btn-primary">Next: Appointment Details</button>
    </EditForm>

    @if (showStep2)
    {
        <hr />
        <h4>Step 2: Appointment Details</h4>
        <EditForm EditContext="appointmentEditContext" OnSubmit="HandleCheckAvailability" class="mb-4">
            <DataAnnotationsValidator />
            <CustomValidator @ref="customValidator" />

            <div class="mb-3">
                <label class="form-label" for="doctor">Preferred Doctor</label>
                <InputSelect id="doctor" class="form-control" @bind-Value="appointmentDetails.Doctor"
                    @bind-Value:after="OnDoctorChanged">
                    <option value="">-- Select --</option>
                    @foreach (var doc in doctors)
                    {
                        <option value="@doc">@doc</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => appointmentDetails.Doctor" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="date">Date</label>
                <InputDate id="date" class="form-control" @bind-Value="appointmentDetails.Date"
                    @bind-Value:after="OnDateChanged" />
                <ValidationMessage For="() => appointmentDetails.Date" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="timeSlot">Time Slot</label>
                <InputSelect id="timeSlot" class="form-control" @bind-Value="appointmentDetails.TimeSlot">
                    <option value="">-- Select --</option>
                    @foreach (var slot in availableSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => appointmentDetails.TimeSlot" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="reason">Reason for Visit</label>
                <InputTextArea id="reason" class="form-control" rows="3"
                    @bind-Value="appointmentDetails.ReasonForVisit" />
                <ValidationMessage For="() => appointmentDetails.ReasonForVisit" />
            </div>

            <button type="submit" class="btn btn-success" disabled="@isSubmitting">
                @(isSubmitting ? "Checking..." : "Check Availability & Book")
            </button>
        </EditForm>
    }
}

@code {
    private PatientInfoModel patientInfo = new();
    private AppointmentDetailsModel appointmentDetails = new();

    private EditContext patientEditContext = null!;
    private EditContext appointmentEditContext = null!;
    private CustomValidator? customValidator;

    private bool showStep2;
    private bool isSubmitting;
    private bool isConfirmed;

    private List<string> doctors = [];
    private List<string> availableSlots = [];

    protected override async Task OnInitializedAsync()
    {
        patientEditContext = new EditContext(patientInfo);
        appointmentEditContext = new EditContext(appointmentDetails);
        doctors = await AppointmentSvc.GetDoctorsAsync();
    }

    private void HandleStep1Submit()
    {
        showStep2 = true;
    }

    private async Task OnDoctorChanged()
    {
        appointmentDetails.TimeSlot = null;
        await LoadSlots();
    }

    private async Task OnDateChanged()
    {
        appointmentDetails.TimeSlot = null;
        await LoadSlots();
    }

    private async Task LoadSlots()
    {
        if (!string.IsNullOrEmpty(appointmentDetails.Doctor) && appointmentDetails.Date.HasValue)
        {
            availableSlots = await AppointmentSvc.GetAvailableSlotsAsync(
                appointmentDetails.Doctor, appointmentDetails.Date.Value);
        }
        else
        {
            availableSlots = [];
        }
    }

    private async Task HandleCheckAvailability()
    {
        customValidator?.ClearErrors();

        if (!appointmentEditContext.Validate())
        {
            return;
        }

        // Future-date check (DataAnnotations handles it, but double-check)
        if (appointmentDetails.Date.HasValue
            && appointmentDetails.Date.Value <= DateOnly.FromDateTime(DateTime.Today))
        {
            return;
        }

        isSubmitting = true;
        try
        {
            var errors = await AppointmentSvc.ValidatePatientAsync(
                patientInfo.Email!,
                patientInfo.InsuranceProvider!,
                appointmentDetails.Doctor!,
                appointmentDetails.TimeSlot!);

            if (errors.Count > 0)
            {
                // Route Email errors to step-1 context via step-2 custom validator
                // since the Email field lives on a different EditContext, we handle it specially
                var step2Errors = new Dictionary<string, List<string>>();
                foreach (var (field, messages) in errors)
                {
                    if (field == nameof(PatientInfoModel.Email))
                    {
                        // Show on step-2 form via a mapped field so it renders inline
                        step2Errors[field] = messages;
                    }
                    else
                    {
                        step2Errors[field] = messages;
                    }
                }
                customValidator!.DisplayErrors(step2Errors);
                return;
            }

            isConfirmed = true;
        }
        finally
        {
            isSubmitting = false;
        }
    }
