@code {
    private AppointmentFormModel model = new();
    private EditContext editContext = null!;
    private CustomValidator? customValidator;

    private bool showStep2;
    private bool isSubmitting;
    private bool isConfirmed;

    private List<string> doctors = [];
    private List<string> availableSlots = [];

    private static readonly string[] Step1Fields =
        [nameof(AppointmentFormModel.Name), nameof(AppointmentFormModel.Email),
         nameof(AppointmentFormModel.Phone), nameof(AppointmentFormModel.InsuranceProvider)];

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(model);
        doctors = await AppointmentSvc.GetDoctorsAsync();
    }

    private async Task HandleSubmit()
    {
        customValidator?.ClearErrors();

        if (!showStep2)
        {
            // Validate only step 1 fields
            var isStep1Valid = ValidateStep1();
            if (isStep1Valid)
            {
                showStep2 = true;
            }
            return;
        }

        // Full form validation (step 1 + step 2)
        if (!editContext.Validate())
        {
            return;
        }

        isSubmitting = true;
        try
        {
            var errors = await AppointmentSvc.ValidatePatientAsync(
                model.Email!, model.InsuranceProvider!, model.Doctor!, model.TimeSlot!);

            if (errors.Count > 0)
            {
                customValidator!.DisplayErrors(errors);
                return;
            }

            isConfirmed = true;
        }
        finally
        {
            isSubmitting = false;
        }
    }

    private bool ValidateStep1()
    {
        var results = new List<System.ComponentModel.DataAnnotations.ValidationResult>();
        var ctx = new System.ComponentModel.DataAnnotations.ValidationContext(model);
        bool allValid = true;

        // Clear any prior custom errors before re-validating
        customValidator?.ClearErrors();
        var errors = new Dictionary<string, List<string>>();

        foreach (var fieldName in Step1Fields)
        {
            var prop = typeof(AppointmentFormModel).GetProperty(fieldName)!;
            var value = prop.GetValue(model);
            var fieldResults = new List<System.ComponentModel.DataAnnotations.ValidationResult>();
            var fieldCtx = new System.ComponentModel.DataAnnotations.ValidationContext(model)
            {
                MemberName = fieldName
            };

            if (!Validator.TryValidateProperty(value, fieldCtx, fieldResults))
            {
                allValid = false;
                errors[fieldName] = fieldResults.Select(r => r.ErrorMessage!).ToList();
            }
        }

        if (!allValid)
        {
            customValidator!.DisplayErrors(errors);
        }

        return allValid;
    }

    private async Task OnDoctorChanged()
    {
        model.TimeSlot = null;
        await LoadSlots();
    }

    private async Task OnDateChanged()
    {
        model.TimeSlot = null;
        await LoadSlots();
    }

    private async Task LoadSlots()
    {
        if (!string.IsNullOrEmpty(model.Doctor) && model.Date.HasValue)
        {
            availableSlots = await AppointmentSvc.GetAvailableSlotsAsync(
                model.Doctor, model.Date.Value);
        }
        else
        {
            availableSlots = [];
        }
    }
}

